import sys


def main():
    rows = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        cells = [cell.strip() for cell in line.split("|")]
        rows.append(cells)

    if not rows:
        return

    # Determine column widths
    widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    # Determine if columns are numeric
    is_numeric = []
    for i in range(len(widths)):
        numeric = False
        for row in rows[1:]:  # Skip header row
            cell = row[i]
            if cell:
                # Check if cell is a number
                if cell.replace('.', '', 1).replace('-', '', 1).isdigit():
                    numeric = True
                    break
        is_numeric.append(numeric)

    # Format and print header
    header_row = rows[0]
    formatted_header = []
    for cell, width, num_col in zip(header_row, widths, is_numeric):
        if num_col:
            formatted_header.append(cell.rjust(width))
        else:
            formatted_header.append(cell.ljust(width))
    print(" | ".join(formatted_header))

    # Print separator line
    print("-+-".join("-" * w for w in widths))

    # Format and print data rows
    for row in rows[1:]:
        formatted_row = []
        for cell, width, num_col in zip(row, widths, is_numeric):
            if num_col:
                formatted_row.append(cell.rjust(width))
            else:
                formatted_row.append(cell.ljust(width))
        print(" | ".join(formatted_row))


if __name__ == "__main__":
    main()
